/**
 * The simulated services of the benchmark: released (pseudo) names, number of
 * tools, the dock tile and icon of each service's app in the desktop GUI, and
 * a few example tool names. Generated by scripts/export_services.py from the
 * tool-source catalog and the GUI's app manifests, one file per release:
 *
 *   v1.0.0  src/data/services.json; the script checks the counts against the
 *           paper (35 services, 809 tools)
 *   v1.1.0  src/data/services.v1.1.0.json; the same services in the same
 *           order, with the tool counts of that release's catalog
 *
 * The one-line description of each service is page copy and comes from
 * src/content/services.ts.
 */
import paperData from '../data/services.json';
import releaseData from '../data/services.v1.1.0.json';
import { SERVICE_DESCRIPTIONS } from '../content/services';
import { LATEST_RELEASE, PAPER_RELEASE, useRelease, type Release } from './release';

export interface Service {
  id: string;
  /** Released service name, for example "Gridwell Mail". */
  name: string;
  /** Short form for places with little room, for example "Mail". */
  label: string;
  tools: number;
  /** CSS background of the app's dock tile in the desktop GUI. */
  tile: string;
  /** File name of the app's icon under gui/icons/. */
  icon: string;
  /** What the service is and what its tools work on, in one line; empty if none is written. */
  description: string;
  examples: string[];
  /** Catalog id of the first tool the tool explorer lists for the service, for example "phone.make_call". */
  firstTool: string;
  /** The name of every tool of the service, in the tool explorer's order. A tool's catalog id is "<service id>.<name>". */
  toolNames: string[];
}

/** The services of one release, the one with the most tools in v1.0.0 first, and their tools in total. */
export interface ServiceSet { services: Service[]; toolCount: number }

function read(data: { services: Omit<Service, 'description'>[] }): ServiceSet {
  const services = data.services.map(service => ({ ...service, description: SERVICE_DESCRIPTIONS[service.id] ?? '' }));
  return { services, toolCount: services.reduce((sum, service) => sum + service.tools, 0) };
}

export const SERVICE_SETS: Record<Release, ServiceSet> = { [PAPER_RELEASE]: read(paperData), [LATEST_RELEASE]: read(releaseData) };
/** Both releases have the same services, in the same order. */
export const SERVICE_COUNT = SERVICE_SETS[PAPER_RELEASE].services.length;

/** The services of the release selected on the page. */
export function useServices(): ServiceSet {
  return SERVICE_SETS[useRelease()];
}
